  // ── a migration ─────────────────────────────────────────────────────────
  eq('U47 cria duplas com membro_b OPCIONAL (técnico sem par continua aparecendo)',
     /membro_b\s+uuid REFERENCES public\.profiles\(id\)/.test(u47), true);
