  eq('o <svg> do mapa tem user-select:none (nos 3 prefixos) — arrastar não pode selecionar o nome de um bairro',
     /userSelect: "none",\s*\n\s*WebkitUserSelect: "none",\s*\n\s*MozUserSelect: "none",/.test(mc3),
     true);
