  eq('R125: "Fluxo e ritmo" saiu do painel (o que ele mostrava segue na biblioteca de indicadores)',
     /titulo="Fluxo e ritmo"/.test(op3), false);
  // só as linhas de CÓDIGO: o comentário do topo cita o card "Duplas de
